import json,collections as C
L=lambda e: json.load(open(e+".json"))
wo=L("WorkOrder"); da=L("DispatchAssignment"); ca={c["id"]:c for c in L("Callout")}
print(C.Counter(w["type"] for w in wo))
print(C.Counter((w["type"],w["reason"]) for w in wo if w["type"] in("ROAD_CALL","HYDRAULIC_REPAIR","BATTERY_REPLACED")))
print("--- road calls / repairs")
for w in sorted(wo,key=lambda w:w["openedLocal"]):
    if w["type"] in ("ROAD_CALL","HYDRAULIC_REPAIR","BATTERY_REPLACED"): print(w["openedLocal"],w["vehicleName"],w["type"],w["reason"],w["meterReadings"],w["notes"][:60])
print("--- dispatch status", C.Counter(d["status"] for d in da))
for d in sorted(da,key=lambda d:d["startLocal"] or ""):
    if d["status"]!="COMPLETED": print(ca[d["calloutId"]]["date"],d["vehicleName"],d["routeId"],d["status"],d["startLocal"],d["endLocal"],d["fractionOfRoute"],d["reassignedFrom"])
print("--- trucks per callout")
for cid,c in sorted(ca.items(),key=lambda x:x[1]["date"]):
    t={d["vehicleName"] for d in da if d["calloutId"]==cid}
    allt={f"T-{i}" for i in range(101,131)}
    print(c["date"],len(t),"missing:",sorted(allt-t))
EOF

