import json,collections as C
from datetime import datetime,timedelta
R=lambda e: json.load(open(f"data/raw/{e}.json"))
das=R("DeviceAssignment"); sd=R("StatusData"); wo=R("WorkOrder")
hourly={h["datetime_local"]:h["temp_c"] for h in json.load(open("data/weather/hourly.json"))}
def truck(dev,t):
    for a in das:
        if a["device"]["id"]==dev and a["activeFrom"]<=t<a["activeTo"]: return a["vehicleName"]
volt={}
for s in sd:
    if s["diagnostic"]["id"]!="DiagnosticBatteryRestingVoltageId": continue
    loc=(datetime.strptime(s["dateTime"][:19],"%Y-%m-%dT%H:%M:%S")-timedelta(hours=5)).date()
    volt[(truck(s["device"]["id"],s["dateTime"]),loc)]=s["data"]
def low(d):  # overnight low: prev 18:00 -> 08:00
    t=datetime.combine(d,datetime.min.time())-timedelta(hours=6); v=[]
    for i in range(14):
        x=hourly.get((t+timedelta(hours=i)).strftime("%Y-%m-%d %H:%M")); 
        if x is not None: v.append(x)
    return min(v) if v else None
ns={(w["vehicleName"],datetime.strptime(w["openedLocal"][:10],"%Y-%m-%d").date()) for w in wo if w.get("reason")=="NO_START"}
rows=[]
for (t,d),v in volt.items():
    m=d+timedelta(days=1)
    if (m.month in (12,1)) and low(m) is not None: rows.append((t,m,v,low(m),(t,m) in ns))
print("no-start events:")
for r in sorted(r for r in rows if r[4]): print(" ",r[0],r[1],"volt",r[2],"low",r[3])
print("matched",sum(r[4] for r in rows),"of",len(ns))
# grid: failure rate by volt bucket x temp bucket
g=C.defaultdict(lambda:[0,0])
for t,m,v,l,y in rows:
    g[(min(v,12.5)//0.1/10 if v<12.5 else 12.5, "<=-10" if l<=-10 else ("-10..-5" if l<=-5 else ">-5"))][0 if y else 1]+=1
for k in sorted(g): print(k,"fail",g[k][0],"ok",g[k][1])
EOF
