import json,collections as C
from datetime import datetime,timedelta
R=lambda e: json.load(open(f"data/raw/{e}.json"))
das=R("DeviceAssignment"); sd=R("StatusData"); wo=R("WorkOrder"); fd=R("FaultData"); da=R("DispatchAssignment"); ca=R("Callout")
def truck(dev,t):
    for a in das:
        if a["device"]["id"]==dev and a["activeFrom"]<=t<a["activeTo"]: return a["vehicleName"]
def loc(z): return datetime.strptime(z[:19],"%Y-%m-%dT%H:%M:%S")-timedelta(hours=5)
pto=C.defaultdict(list)
for s in sd:
    if s["diagnostic"]["id"]=="DiagnosticPtoHoursId": pto[truck(s["device"]["id"],s["dateTime"])].append((loc(s["dateTime"]),s["data"]))
for t in pto: pto[t].sort()
svc=C.defaultdict(list)
for w in wo:
    if w["type"] in("HYDRAULIC_SERVICE","HYDRAULIC_REPAIR"): svc[w["vehicleName"]].append((w["openedLocal"],w["type"],(w["meterReadings"] or {}).get("ptoHours")))
print("hyd services per truck:",{t:len(v) for t,v in sorted(svc.items())})
print("example T-114:",sorted(svc["T-114"]))
def pto_at(t,when):
    xs=[v for d,v in pto[t] if d<=when]; return xs[-1] if xs else None
def since_service(t,when):
    s=[x for x in sorted(svc[t]) if x[0]<=when.strftime("%Y-%m-%dT%H:%M:%S")]
    if not s: return None,None
    last=s[-1]; base=last[2] if last[2] is not None else pto_at(t,datetime.strptime(last[0],"%Y-%m-%dT%H:%M:%S"))
    p=pto_at(t,when); return (None if base is None or p is None else round(p-base,1)), last
hydfail={(w["vehicleName"],w["openedLocal"][:10]) for w in wo if w.get("reason")=="HYDRAULIC_FAILURE"}
fault=C.defaultdict(list)
for f in fd: fault[truck(f["device"]["id"],f["dateTime"])].append((loc(f["dateTime"]),f["diagnostic"]["id"]))
print("--- per callout x truck: pto since hyd service, HYD-PRESS-LOW in last 7d")
rows=[]
for c in ca:
    when=datetime.strptime(c["calloutLocal"],"%Y-%m-%dT%H:%M:%S")
    trucks={d["vehicleName"] for d in da if d["calloutId"]==c["id"]}
    for t in trucks:
        ss,last=since_service(t,when)
        hp=sum(1 for d,k in fault[t] if k=="HYD-PRESS-LOW" and when-timedelta(days=7)<=d<when)
        hpall=sum(1 for d,k in fault[t] if k=="HYD-PRESS-LOW" and d<when and (last is None or d.strftime("%Y-%m-%dT%H:%M:%S")>=last[0]))
        rows.append((c["date"],t,ss,hp,hpall,(t,c["date"]) in hydfail))
for r in sorted(rows,key=lambda r:-(r[2] or 0))[:25]: print(" ",r)
print("failures:",[r for r in rows if r[5]])
EOF
